#include "ksControllerBoundary.h"
#include <stdexcept>
namespace ks{namespace{SerialDirectPartialTest partialTest=nullptr;using T=SerialDirectTask;using S=T::Stage;using K=T::Kind;struct Point{unsigned location,length;};Point point(const T&t){switch(t.stage()){case S::Hold:return{0x119c,2};case S::ReadStatus:return{0x119e,2};case S::TestReady:return{0x11a0,2};case S::AdmitReady:return{0x11a2,2};case S::WriteData:return{0x11a4,2};case S::MaskStatus:return{0x11a6,2};case S::WriteStatus:return{0x11a8,2};case S::Restore:return{0x11aa,2};case S::Finish:return{t.kind()==K::Noop?0x119au:0x11acu,2};default:throw std::runtime_error("Invalid serial direct stage");}}}
bool SerialDirectCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(pc==0x119a||pc==0x119c){if(selected)throw std::runtime_error("Overlapping serial direct");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Serial direct capacity");selected->emplace(pc==0x119a?K::Noop:K::Write,h.getSP());++started;}if(!selected||point((**selected).task).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(t).length);auto&v=h.regs;auto clock=[&](T::Write w){unsigned at=w==T::Write::Data?0xffff8b:0xffff8c;return (at&1)&&h.lastwrite==int(at-1)?0u:1u;};auto cost=t.nextClocks(clock);t.advanceBefore(cost,[&](T::Read r){return r==T::Read::Input?uint8_t(v[0].rh):uint8_t(h.read8(0xffff8c));},[&](T::Write w,uint8_t value){f.store8(w==T::Write::Data?0xffff8b:0xffff8c,int8_t(value));},clock);switch(stage){case S::Hold:f.push(v[0].r);(**selected).depth+=2;break;case S::ReadStatus:f.move(v[0].rl,int8_t(t.status()));break;case S::TestReady:flag(h,4,(t.status()&128)==0);break;case S::MaskStatus:v[0].rl&=127;value(h,v[0].rl);break;case S::Restore:f.pop(v[0].r);(**selected).depth-=2;break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::Finish)h.pc=h.makepc(point(t).location);if(h.cycles-before!=cost)throw std::runtime_error("Serial direct clocks differ");return true;}}

namespace ks{void setSerialDirectPartialForTests(SerialDirectPartialTest fn){partialTest=fn;}}
